<style>
/* Sionika: a product page on the lab plane. Gold belongs to the product; chords are the one ornament, and they are real. */
:root { --gold: var(--sionika); }
.s-hero { padding-block: calc(var(--nav-h) + 64px) 0; position: relative; overflow: hidden; border-bottom: 1px solid var(--line); }
.s-hero .wrap { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); gap: 40px; align-items: end; }
.crumb { font: 400 13px var(--f-mono); color: var(--muted); }
.crumb a { color: var(--ink-2); text-decoration: none; }
.s-title { display: flex; align-items: center; gap: 18px; margin-top: 22px; }
.s-title svg { width: clamp(56px, 7vw, 96px); height: auto; fill: var(--gold); flex: none; }
.s-title h1 { font: 400 clamp(72px, 11vw, 150px)/0.9 "Forum", "Times New Roman", serif; letter-spacing: -0.01em; }
.s-sub { margin-top: 22px; font: 500 clamp(20px, 2vw, 26px)/1.3 var(--f-sans); }
.s-hero .lede { margin-top: 14px; }
.s-meta { display: flex; flex-wrap: wrap; gap: 6px 22px; margin-top: 24px; font: 400 13px var(--f-mono); color: var(--muted); }
.s-acts { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 28px; padding-bottom: 64px; }
.btn.gold { background: var(--gold); border-color: var(--gold); color: #000; }
.btn.gold:hover { background: transparent; color: var(--gold); }
.duo { position: relative; height: clamp(420px, 46vw, 600px); }
.phone { border-radius: 30px; padding: 6px; background: #0e0e0e; box-shadow: 0 0 0 1px #262626; }
.phone img { border-radius: 25px; width: 100%; aspect-ratio: 1179 / 2556; object-fit: cover; background: #111; }
.duo .phone { position: absolute; bottom: -18%; width: 47%; }
.duo .p1 { left: 4%; } .duo .p2 { right: 2%; bottom: -8%; }
@media (prefers-reduced-motion: no-preference) {
  .s-title, .s-sub, .s-hero .lede, .s-meta, .s-acts { animation: up .9s var(--ease) both; }
  .s-sub { animation-delay: .1s; } .s-hero .lede { animation-delay: .18s; } .s-meta { animation-delay: .24s; } .s-acts { animation-delay: .3s; }
  .duo .p1 { animation: rise 1.3s var(--ease) .2s both; } .duo .p2 { animation: rise 1.3s var(--ease) .35s both; }
}
@keyframes up { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
@keyframes rise { from { opacity: 0; transform: translateY(60px); } to { opacity: 1; transform: none; } }

.facts4 { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-bottom: 1px solid var(--line); }
.facts4 div { padding: 26px 20px 26px 0; display: grid; gap: 6px; }
.facts4 div + div { border-left: 1px solid var(--line); padding-left: 20px; }
.facts4 b { font: 400 clamp(32px, 3.4vw, 44px)/1 "Forum", serif; }
.facts4 span { color: var(--ink-2); font-size: 14.5px; }

/* transposition demo */
.demo { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr); gap: 48px; align-items: start; }
.sheet { border: 1px solid var(--line); background: var(--bg-2); padding: 22px 22px 18px; min-width: 0; }
.sheet .bar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; padding-bottom: 16px; border-bottom: 1px solid var(--line); }
.sheet .song b { display: block; font-weight: 500; }
.sheet .song span { font-size: 13.5px; color: var(--muted); }
.tr { display: inline-flex; align-items: center; border: 1px solid var(--line-2); }
.tr button { font: 500 18px/1 var(--f-mono); color: var(--ink); background: none; border: 0; width: 44px; height: 40px; cursor: pointer; }
.tr button:hover { background: var(--ink); color: #000; }
.tr output { font: 500 15px var(--f-mono); min-width: 52px; text-align: center; border-inline: 1px solid var(--line-2); line-height: 40px; }
.lyrics { margin: 18px 0 0; font: 400 clamp(12.5px, 1.25vw, 15px)/1.45 var(--f-mono); overflow-x: auto; white-space: pre; }
.lyrics .sec-l { color: var(--muted); display: block; margin-bottom: 6px; }
.lyrics .ch { color: var(--gold); font-weight: 600; display: block; min-height: 1.45em; }
.lyrics .ly { color: var(--ink); display: block; margin-bottom: 8px; }
.lyrics .c { display: inline-block; transition: transform .35s var(--ease), opacity .35s; }
.lyrics .c.flip { transform: translateY(-6px); opacity: 0; }
.keyline { margin-top: 14px; font: 400 13px var(--f-mono); color: var(--muted); }

/* feature blocks */
.feat { display: grid; grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.3fr); gap: 56px; align-items: start; }
.feat.flip { grid-template-columns: minmax(0, 1.3fr) minmax(0, 0.9fr); }
.feat.flip > :first-child { order: 2; }
.feat .txt { display: grid; gap: 20px; position: sticky; top: calc(var(--nav-h) + 32px); }
.feat h2 { font: 600 clamp(28px, 3.4vw, 42px)/1.08 var(--f-wide); letter-spacing: -0.02em; }
.feat p { color: var(--ink-2); max-width: 52ch; }
.flist { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line); }
.flist li { padding: 12px 0; border-bottom: 1px solid var(--line); color: var(--ink-2); font-size: 15.5px; }
.flist b { color: var(--ink); font-weight: 500; }
.shots { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }
.shots.two { grid-template-columns: repeat(2, minmax(0, 1fr)); max-width: 560px; }
figure { margin: 0; display: grid; gap: 10px; min-width: 0; }
figcaption { font: 400 13px var(--f-mono); color: var(--muted); }
.shots .phone { transition: transform .6s var(--ease); }
.shots figure:hover .phone { transform: translateY(-6px); }

.pal-head { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: end; gap: 20px; margin-bottom: 32px; }
.seg { display: flex; border: 1px solid var(--line-2); }
.seg button { font: 500 14px var(--f-sans); color: var(--ink-2); background: none; border: 0; padding: 10px 16px; cursor: pointer; }
.seg button + button { border-left: 1px solid var(--line-2); }
.seg button[aria-pressed="true"] { background: var(--ink); color: #000; }
.shots.five { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 14px; }

.timeline { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line); }
.timeline li { display: grid; grid-template-columns: 140px minmax(0, 1fr); gap: 20px; padding: 18px 0; border-bottom: 1px solid var(--line); }
.timeline time { font: 400 13px var(--f-mono); color: var(--gold); }
.timeline b { font-weight: 500; }
.timeline p { color: var(--ink-2); font-size: 15.5px; margin-top: 4px; }
.specs { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); border-top: 1px solid var(--line); }
.specs div { padding: 22px 24px 24px 0; border-bottom: 1px solid var(--line); display: grid; gap: 8px; align-content: start; }
.specs div:not(:nth-child(3n+1)) { border-left: 1px solid var(--line); padding-left: 24px; }
.specs b { font: 400 26px/1.15 "Forum", serif; }
.specs span { color: var(--ink-2); font-size: 15px; }

.get { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 24px 48px; align-items: end; }
.get h2 { font: 400 clamp(44px, 7vw, 96px)/0.95 "Forum", serif; }
.get p { color: var(--ink-2); max-width: 54ch; margin-top: 18px; }
.get .handle { font: 500 15px var(--f-mono); color: var(--gold); margin-top: 14px; user-select: all; }

@media (max-width: 960px) {
  .s-hero .wrap, .demo, .feat, .feat.flip, .get { grid-template-columns: minmax(0, 1fr); }
  .feat.flip > :first-child { order: 0; }
  .feat .txt { position: static; }
  .duo { height: 460px; max-width: 520px; width: 100%; margin-inline: auto; }
  .shots.five { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .specs { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .specs div:not(:nth-child(3n+1)) { border-left: 0; padding-left: 0; }
  .specs div:nth-child(2n) { border-left: 1px solid var(--line); padding-left: 20px; }
}
@media (max-width: 640px) {
  .s-hero { padding-top: calc(var(--nav-h) + 36px); }
  .s-acts { padding-bottom: 36px; }
  .duo { height: 380px; }
  .facts4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .facts4 div:nth-child(3) { border-left: 0; padding-left: 0; }
  .facts4 div:nth-child(n+3) { border-top: 1px solid var(--line); }
  .shots { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
  .shots:not(.five) > figure:nth-child(3) { display: none; }
  .shots.five { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .shots.five > figure:last-child { display: none; }
  .timeline li { grid-template-columns: minmax(0, 1fr); gap: 4px; }
  .specs { grid-template-columns: minmax(0, 1fr); }
  .specs div:nth-child(2n) { border-left: 0; padding-left: 0; }
  .sheet { padding: 16px 14px; }
}
</style>
</head>
