<script src="../assets/lab.js"></script>
<script>
(() => {
  /* transposition: the same rule as ChordTransposer.kt in the app */
  const SHARP = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'], FLAT = ['C', 'Db', 'D', 'Eb', 'E', 'F', 'Gb', 'G', 'Ab', 'A', 'Bb', 'B'];
  const IDX = { C: 0, 'C#': 1, Db: 1, D: 2, 'D#': 3, Eb: 3, E: 4, Fb: 4, F: 5, 'E#': 5, 'F#': 6, Gb: 6, G: 7, 'G#': 8, Ab: 8, A: 9, 'A#': 10, Bb: 10, B: 11, H: 11, Cb: 11 };
  const RE = /^([A-Ha-h][#b]?)((?:m(?:aj|in)?|maj|dim|aug|sus|add|dom)?\d*(?:[\/#+-]\d+)?(?:\([^)]*\))?)(\/([A-Ha-h][#b]?))?$/;
  const up1 = s => s.charAt(0).toUpperCase() + s.slice(1);
  function transpose(ch, n) {
    if (!n) return ch;
    const m = ch.match(RE); if (!m) return ch;
    const root = up1(m[1]), mod = m[2], bass = m[4] ? up1(m[4]) : null;
    if (IDX[root] === undefined) return ch;
    const list = root.includes('b') || (bass && bass.includes('b')) ? FLAT : SHARP;
    const nr = list[((IDX[root] + n) % 12 + 12) % 12];
    return nr + mod + (bass ? '/' + list[((IDX[bass] + n) % 12 + 12) % 12] : '');
  }
  const RAW = ["                     C               G      D/F#       Em", "Славь, душа, Господа, Славь, душа,", "C               G   Dsus4  D", "Имя Святое Его.", "         C                        Em    C       D  Em", "Пой Ему, как никогда, пой, душа,", "    C             D           C/G   G   C/G   G", "Благослови Господа."];
  // chord lines in the catalogue are spaced for a proportional font; squeeze them onto the lyric line
  const pairs = [];
  for (let i = 0; i < RAW.length; i += 2) {
    const cl = RAW[i], ly = RAW[i + 1], k = Math.min(1, (ly.length + 2) / Math.max(cl.length, 1)), chords = [];
    cl.replace(/\S+/g, (c, at) => { chords.push([c, Math.round(at * k)]); return c; });
    pairs.push([chords, ly]);
  }
  const box = document.getElementById('lyrics'), out = document.getElementById('semi'), keyline = document.getElementById('keyline');
  let semi = 0;
  function render(anim) {
    box.replaceChildren();
    const lab = document.createElement('span'); lab.className = 'sec-l'; lab.textContent = 'Припев'; box.append(lab);
    pairs.forEach(([chords, ly]) => {
      const line = document.createElement('span'); line.className = 'ch';
      let col = 0;
      chords.forEach(([c, at]) => {
        const t = transpose(c, semi), pos = Math.max(at, col);
        line.append(document.createTextNode(' '.repeat(pos - col)));
        const s = document.createElement('span'); s.className = 'c' + (anim ? ' flip' : ''); s.textContent = t; line.append(s);
        col = pos + t.length + 1; line.append(document.createTextNode(' '));
      });
      const l = document.createElement('span'); l.className = 'ly'; l.textContent = ly;
      box.append(line, l);
    });
    if (anim) requestAnimationFrame(() => requestAnimationFrame(() => box.querySelectorAll('.c.flip').forEach(e => e.classList.remove('flip'))));
    out.textContent = (semi > 0 ? '+' : semi < 0 ? '−' : '') + Math.abs(semi);
    keyline.textContent = semi ? `тональность C → ${transpose('C', semi)}` : 'тональность C, как в оригинале';
  }
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  document.getElementById('up').addEventListener('click', () => { semi = semi >= 11 ? -11 : semi + 1; render(!reduce); });
  document.getElementById('down').addEventListener('click', () => { semi = semi <= -11 ? 11 : semi - 1; render(!reduce); });
  render(false);

  /* palette light / dark */
  const buttons = [...document.querySelectorAll('.seg button[data-pal]')];
  buttons.forEach(b => b.addEventListener('click', () => {
    buttons.forEach(x => x.setAttribute('aria-pressed', String(x === b)));
    document.querySelectorAll('img[data-pal-img]').forEach(img => { img.src = img.src.replace(/(d11|11)_palette_/, b.dataset.pal + '_palette_'); });
  }));
})();
</script>
